// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен (свежий бандл).
import { test, expect } from '@playwright/test';
import { publicPaths, prepareReadOnly, LOAD } from './ssr-infra.helpers';

test.use({ serviceWorkers: 'block' });

declare global {
  interface Window { __qaSeoAtDcl?: string }
}

test.describe('SSR/SSG — браузер с JS', () => {
  test('Публичные страницы: SSR-блок скрыт к DOMContentLoaded и удалён после React, 0 ошибок консоли #be4863 @desktop @prod-safe', async ({ page, context, request }) => {
    const paths = await publicPaths(request);
    await prepareReadOnly(context);
    // Состояние блока ровно в момент DOMContentLoaded: 'removed' или computed display.
    await context.addInitScript(() => {
      document.addEventListener('DOMContentLoaded', () => {
        const el = document.querySelector('[data-seo-body]') as HTMLElement | null;
        window.__qaSeoAtDcl = el ? `${getComputedStyle(el).display}|${el.getClientRects().length}` : 'removed';
      });
    });

    for (const path of paths) {
      await test.step(path, async () => {
        const errors: string[] = [];
        const onConsole = (m: { type(): string; text(): string }) => { if (m.type() === 'error') errors.push(m.text()); };
        const onPageError = (e: Error) => errors.push(`pageerror: ${e.message}`);
        page.on('console', onConsole);
        page.on('pageerror', onPageError);

        await page.goto(path, { waitUntil: 'domcontentloaded' });
        const atDcl = await page.evaluate(() => window.__qaSeoAtDcl);
        expect(atDcl === 'removed' || atDcl === 'none|0', `${path}: на DOMContentLoaded блок скрыт/удалён (${atDcl})`).toBe(true);

        await expect(page.locator('[data-seo-body]'), `${path}: SSR-блок удалён после React`).toHaveCount(0, LOAD);
        await expect(page.locator('#root > :not(style)').first(), `${path}: React-разметка видна`).toBeVisible(LOAD);
        await page.waitForLoadState('load');

        page.off('console', onConsole);
        page.off('pageerror', onPageError);
        expect(errors, `${path}: console errors / pageerror`).toEqual([]);
      });
    }
  });
});
